import React, {useState} from 'react';
import {Link} from 'react-router-dom';
// import {VscMenu, AiOutlineClose} from 'react-icons/all'
import logo from "../../../img/favicon.ico";
import './Navbar.css'
import '../../Button.css';
import {Button} from "../../Button";
import Popup from "../../Popup/Popup";
import {ApiMail} from "../../../api";
import PopupLogin from "../../Popup/PopupLogin";

function Navbar() {
    const [isOpenLoginForm, setOpenLoginForm] = useState(false);

    const handleOpenLoginForm = () => {
        setOpenLoginForm(!isOpenLoginForm);
    }


    return (
        <>
            <div className="navbar">
                <Link to='/' className="navbar-title">
                    <img src={logo} className={'logo'} alt={logo}/>
                    <div className={'title'}>UniAdvisor.it</div>
                </Link>
                <div className="menu-content">
                    <Button buttonStyle='btn--outline' onClick={handleOpenLoginForm}>ACCEDI/REGISTRATI</Button>
                    {isOpenLoginForm && <PopupLogin/>}
                </div>
            </div>
        </>
    );

}

export default Navbar;
